  out.push(`== FAILED STEPS (${failed.length}) ==`, ...failed.slice(0, 6).map(r => `#${r.i} ${JSON.stringify(r.step).slice(0, 80)} -> ${r.detail}`));
  const cl = chat.slice(-Math.max(5, Math.min(30, 119 - out.length))).map(c => `${c.pos === 'game_info' ? '[actionbar] ' : ''}${c.text}`.slice(0, 200));
